import 'quote.dart';

/// Quotes on character, equanimity, perspective and the choice of values.
const List<Quote> kQuotesCharacter = <Quote>[
  Quote(en: 'You have power over your mind, not outside events. Realize this, and you will find strength.', zh: '你能掌控的是自己的心，而非外物；明白这一点，你便有了力量。'),
  Quote(en: 'The happiness of your life depends upon the quality of your thoughts.', zh: '生活的幸福，取决于你思想的质量。'),
  Quote(en: 'No man is free who is not master of himself.', zh: '不能主宰自己的人，算不上自由人。'),
  Quote(en: 'It is not events that disturb people, but their judgments about them.', zh: '扰乱人心的不是事情本身，而是人对事情的看法。'),
  Quote(en: 'Between what happens to you and what you do next lies a space that belongs entirely to you.', zh: '在你遭遇的事与接下来的举动之间，有一片完全属于你的余地。'),
  Quote(en: 'A calm mind is not a mind without storms; it is a mind that has learned to let the storms pass.', zh: '平静的心并非没有风暴，而是学会了让风暴自行过去。'),
  Quote(en: 'You cannot still the wind, but you can trim your sails.', zh: '你无法让风停下，却能调整自己的帆。'),
  Quote(en: 'Anger is an acid that harms the vessel that holds it more than anything it is poured upon.', zh: '愤怒是腐蚀容器本身的酸，伤己甚于所向。'),
  Quote(en: 'When you are offended by a fault in another, turn and examine the same fault in yourself.', zh: '见他人之过而心生不快时，回头看看自己是否也有同样的毛病。'),
  Quote(en: 'The test of a strong character is how it behaves when no one is watching.', zh: '品格的试金石，是无人注视时的所作所为。'),
  Quote(en: 'A narrow mind talks about people, an average mind talks about events, and a great mind talks about ideas.', zh: '心胸狭窄者议论人，平庸者议论事，格局大者议论思想。'),
  Quote(en: 'Greatness is a quiet habit of doing the unglamorous thing well.', zh: '伟大是一种安静的习惯：把不起眼的事做好。'),
  Quote(en: 'To see the whole board is worth more than to win the next move.', zh: '看清整盘棋，胜过赢下眼前一步。'),
  Quote(en: 'The mountain does not boast of its height; it simply stands.', zh: '山不夸耀自己的高度，只是静静立着。'),
  Quote(en: 'He who plants trees he will never sit beneath has understood something about time.', zh: '为他人栽下自己乘不到凉的树，便是懂得了时间。'),
  Quote(en: 'A big heart is not one that holds no grudges but one that keeps giving room for people to change.', zh: '宽大的心胸不是不记怨，而是始终给人留出改变的空间。'),
  Quote(en: 'You can tell the size of a man by the size of the things that make him angry, and by how long he stays angry.', zh: '看他因多大的事动怒、又气多久，便知他胸襟几何。'),
  Quote(en: 'The river reaches the sea not by breaking the rock but by wearing it away patiently.', zh: '河流不是劈开岩石才到海，而是靠长久的磨蚀。'),
  Quote(en: 'You will be misjudged, blamed and forgotten, and none of it will matter as much as what you decide to do with the hours you still have; that choice is yours alone.', zh: '你会被误解、被指责、被遗忘；这些都不及你如何度过余下的时光重要，而这个选择只属于你。'),
  Quote(en: 'Some people grow in stature when the light leaves them; others merely grow old.', zh: '有人在光彩褪去后愈发高大，有人只是变老。'),
  Quote(en: 'Wealth consists not in having great possessions, but in having few wants.', zh: '富有不在于拥有很多，而在于欲求很少。'),
  Quote(en: "A man's worth is not in his purse but in what he would refuse to do for money.", zh: '一个人的价值不在钱袋，而在他为钱不肯做的事。'),
  Quote(en: 'Freedom is not the absence of limits but the choice of which limits to accept.', zh: '自由不是没有限制，而是自己选择接受哪些限制。'),
  Quote(en: 'The price of a thing is the amount of life you exchange for it.', zh: '一件东西的价钱，是你为它付出的那部分生命。'),
  Quote(en: 'To own much is to be owned by much.', zh: '占有许多，便也被许多占有。'),
  Quote(en: 'Choose your habits as carefully as your friends, for both decide who you become and neither can be dismissed overnight.', zh: '选习惯要像选朋友一样谨慎，两者都决定你成为谁，也都不能一夜之间辞掉。'),
  Quote(en: 'A thing worth having is worth paying for in patience as well as in coin.', zh: '值得拥有的东西，除了钱，还要用耐心换。'),
  Quote(en: 'You cannot buy a clear conscience with a full purse.', zh: '再满的钱袋也买不来清白的良心。'),
  Quote(en: 'Simplicity is not the absence of things but the presence of what matters.', zh: '简朴不是东西少，而是要紧之物都在。'),
  Quote(en: 'Every yes costs you a no somewhere else; spend your yeses like rare coin.', zh: '每次答应都在别处换来一次拒绝；把答应当作稀有的钱币来花。'),
  Quote(en: 'The person who has learned to wait without resentment, to work without applause, and to lose without bitterness has found a kind of freedom that no circumstance can take back from him.', zh: '学会不抱怨地等待、无掌声地做事、无怨恨地失去的人，得到了一种任何境遇也夺不走的自由。'),
  Quote(en: 'Knowing others is intelligence; knowing yourself is true wisdom.', zh: '知人者智，自知者明。'),
  Quote(en: 'The first step toward wisdom is to admit how little you know.', zh: '走向智慧的第一步，是承认自己知之甚少。'),
  Quote(en: 'A fool who knows he is a fool is at least on the road; a fool who thinks he is wise has not left home.', zh: '自知愚笨的愚人至少在赶路；自认聪明的愚人还未出门。'),
  Quote(en: 'No one is more dangerous than the man who is certain he is right.', zh: '最危险的人，是确信自己正确的人。'),
  Quote(en: 'Pride builds a wall that keeps out the very counsel it needs.', zh: '骄傲筑起的墙，挡住的恰是它最需要的忠告。'),
  Quote(en: 'We see the faults of others through a telescope and our own through a fog.', zh: '我们用望远镜看别人的过失，蒙着雾看自己的。'),
  Quote(en: 'To listen well is a rarer gift than to speak well.', zh: '善于倾听，比能言善辩更难得。'),
  Quote(en: 'The wise man learns from everyone, the fool only from himself.', zh: '智者向所有人学习，愚者只向自己学习。'),
  Quote(en: 'Half of what we call confidence is merely the fear of seeming unsure.', zh: '我们所谓的自信，有一半只是怕显得不确定。'),
  Quote(en: 'Be humble enough to be corrected and honest enough to correct yourself.', zh: '谦逊到肯被纠正，诚实到能自我纠正。'),
  Quote(en: 'We are all apprentices in a craft that has no masters.', zh: '在这门没有大师的技艺里，我们都只是学徒。'),
  Quote(en: 'The older I grow, the less I know for certain and the more I hold with care.', zh: '年岁越长，我确定的越少，珍重以待的越多。'),
  Quote(en: 'No opinion deserves to become your identity.', zh: '没有哪一种见解值得成为你的身份。'),
  Quote(en: 'Ask yourself not whether you are right, but what would prove you wrong.', zh: '别问自己是否正确，要问什么能证明自己错。'),
  Quote(en: 'Be kind, for everyone you meet is fighting a hard battle.', zh: '待人以善，因为你遇到的每个人都在苦战。'),
  Quote(en: 'Forgiveness does not change the past, but it widens the future.', zh: '宽恕改变不了过去，却能把未来拓宽。'),
  Quote(en: 'To understand everything is to forgive everything.', zh: '全然理解，便是全然宽恕。'),
  Quote(en: 'Listen twice as much as you speak, and you will need far fewer apologies.', zh: '听的比说的多一倍，需要道歉的时候就少得多。'),
  Quote(en: 'Judge a person by how he treats those who can do nothing for him.', zh: '看他如何对待对他毫无用处的人，便可知其人品。'),
  Quote(en: 'A gentle answer turns away anger, but a harsh word stirs up strife.', zh: '温和的回答能平息怒气，尖刻的话却会挑起争端。'),
  Quote(en: 'We are quick to condemn in others what we have quietly excused in ourselves.', zh: '我们苛责他人的，往往是自己悄悄放过的地方。'),
  Quote(en: 'The person who cannot forgive others breaks the bridge over which he must pass.', zh: '不肯宽恕他人的人，拆毁了自己必经的桥。'),
  Quote(en: 'Do not give advice to one who has not asked for it, unless the danger is great.', zh: '除非危险迫近，不要向没有求教的人进言。'),
  Quote(en: 'Silence at the right moment is often the kindest reply.', zh: '恰当时的沉默，往往是最仁慈的回答。'),
  Quote(en: 'The mirror of friendship shows us what we hide from the looking glass.', zh: '朋友这面镜子，照见我们在镜前藏起的东西。'),
  Quote(en: 'To admit a mistake quickly is a form of dignity, not of shame.', zh: '痛快认错，是一种尊严，而非耻辱。'),
  Quote(en: 'The person who insists on being the smartest in the room never learns where he is.', zh: '偏要当屋里最聪明的人，永远弄不清自己身在何处。'),
  Quote(en: 'A modest man learns more in a year than a proud man in ten.', zh: '谦逊的人一年所学，胜过骄傲的人十年。'),
  Quote(en: 'Self-knowledge begins where self-justification ends.', zh: '自知始于自我辩解结束之处。'),
  Quote(en: 'The hard road you are on may be the shortest way to where you need to be.', zh: '你脚下的难路，或许正是通往该去之处的近路。'),
  Quote(en: 'Smooth seas never made a skilled sailor.', zh: '平静的海面练不出好水手。'),
  Quote(en: 'What stands in your way becomes the way once you stop resenting it.', zh: '挡路的东西，一旦不再怨恨，它就成了路。'),
  Quote(en: 'Adversity does not build character so much as reveal it.', zh: '逆境与其说塑造品格，不如说显露品格。'),
  Quote(en: 'No winter lasts forever; no spring skips its turn.', zh: '没有永远的冬天，也没有缺席的春天。'),
  Quote(en: 'The wound is the place where the light enters you.', zh: '伤口，正是光进来的地方。'),
  Quote(en: 'When everything has been taken from you, what remains is what you really are; strip a man of every title and you will meet him at last.', zh: '当一切被夺走，剩下的就是你真实的模样；剥去一个人所有头衔，你终会见到他本人。'),
  Quote(en: 'A tree that has stood through many storms keeps its roots deep and its branches low.', zh: '历经风暴的树，根扎得深，枝条压得低。'),
  Quote(en: 'Fall seven times, stand up eight.', zh: '跌倒七次，第八次站起来。'),
  Quote(en: 'The bamboo bends in the storm and survives; the oak resists and falls.', zh: '暴风雨中，竹子弯曲而存，橡树硬抗而折。'),
  Quote(en: 'The night is darkest just before dawn, and the hour before dawn is the one that tests whether your hope is a feeling or a decision.', zh: '天亮前夜色最浓，而黎明前那一刻，才试出你的希望是情绪还是决定。'),
  Quote(en: 'A scar is a story of survival, not a sign of failure.', zh: '疤痕是幸存的故事，不是失败的标记。'),
  Quote(en: 'What cannot be cured must be endured, and what is endured well is half-way to peace.', zh: '无法治愈的只得承受，承受得好便已近安宁。'),
  Quote(en: 'The rain does not stop for the impatient man, but it does stop.', zh: '雨不会为急躁的人停下，但它总会停。'),
  Quote(en: 'Every loss leaves a room; the question is what you move into it.', zh: '每次失去都空出一个房间，问题是你搬什么进去。'),
  Quote(en: 'Desire is a fire that is easier to starve than to satisfy.', zh: '欲望是火，饿死它比满足它容易。'),
  Quote(en: 'The man who chases two rabbits catches neither.', zh: '追两只兔子的人，一只也抓不到。'),
  Quote(en: 'Enough is a feast that the greedy never taste.', zh: '知足是一桌盛宴，贪婪的人从未尝到。'),
  Quote(en: 'Restraint is not a cage; it is the door through which we leave the cage.', zh: '节制不是牢笼，而是我们走出牢笼的那道门。'),
  Quote(en: 'A craving indulged grows louder; a craving refused grows quieter.', zh: '被纵容的欲望更响，被拒绝的欲望渐静。'),
  Quote(en: 'Nothing you own can follow you past the door of your last day, so the only wealth worth counting is the kindness you have given away and the peace you have kept inside.', zh: '你拥有的东西跟着你走不过最后那道门；唯一值得计算的财富，是你给出去的善意与留在心里的安宁。'),
  Quote(en: 'Comfort is a soft trap, and habit is the hinge of its door.', zh: '安逸是柔软的陷阱，习惯是它的门轴。'),
  Quote(en: 'He who cannot sit still will never hear what quiet has to teach.', zh: '坐不住的人，听不见安静要教的东西。'),
  Quote(en: 'Leisure is not the reward of work; it is the soil in which good work is rooted, and a life without it is a harvest without rain.', zh: '闲暇不是工作的奖赏，而是好工作扎根的土壤；没有闲暇的生活，是没有雨的收成。'),
  Quote(en: 'Patience is not waiting; patience is not complaining while you wait.', zh: '耐心不是等待，而是等待时不抱怨。'),
  Quote(en: 'An insult is only an insult when you agree to carry it.', zh: '侮辱一旦你拒绝背负，就只是一句话。'),
  Quote(en: 'Nothing can give you peace; peace is something you cease to destroy.', zh: '没有什么能给你平静，平静是你不再亲手破坏的东西。'),
  Quote(en: 'He who cannot bear a moment of boredom will never know the pleasure of an unhurried hour, nor the taste of his own company.', zh: '受不了一刻无聊的人，永远不懂不紧不慢的时光之乐，也不懂独处的滋味。'),
  Quote(en: 'Do not ask for an easier life; ask for a stronger back.', zh: '不要祈求更轻松的生活，要祈求更坚实的肩膀。'),
  Quote(en: 'The sleeping tiger is best left sleeping; the idle word is best left unspoken.', zh: '熟睡的老虎别去惊，无用的话别说出口。'),
  Quote(en: 'The loudest person in the room is often the least sure of his own place.', zh: '屋里嗓门最大的人，往往最不确定自己的位置。'),
  Quote(en: 'When the mind is hurried, everything looks urgent and nothing looks important.', zh: '心一急，事事都显得紧急，却无一显得重要。'),
  Quote(en: 'Take a breath before you answer, and you will spare yourself a thousand words that you can never take back.', zh: '答话前先呼吸一次，便能省下千言万语追不回的话。'),
  Quote(en: 'Sorrow is not a weakness; refusing to feel it is.', zh: '悲伤不是软弱，拒绝感受它才是。'),
  Quote(en: 'Any emotion that you can name without obeying has already lost half its power.', zh: '你能叫出名字而不必服从的情绪，已失去一半力量。'),
  Quote(en: 'Worry is a debt paid on a loan you may never take.', zh: '忧虑是在为一笔也许永远不会借的债付利息。'),
  Quote(en: 'Let your anger cool before your hands speak for you.', zh: '等怒气冷却，再让双手替你说话。'),
  Quote(en: 'Let a pause be your first answer to an unexpected blow.', zh: '面对突如其来的打击，让停顿成为第一句回答。'),
  Quote(en: 'An untrained temper is like an unhelmed horse; it goes where it will, not where you need.', zh: '未经约束的脾气像没戴缰绳的马，去它想去的地方，而非你需去的地方。'),
  Quote(en: 'It is easy to govern a city and hard to govern a temper; the second requires a crown no one can give you.', zh: '治理一座城容易，治理脾气难；后者所需的冠冕，无人能替你戴上。'),
  Quote(en: 'The shallowest part of the river is always the loudest.', zh: '河最浅的地方，声音总是最大。'),
  Quote(en: 'A person without a quiet hour is a person without a rudder.', zh: '没有安静时光的人，是一条没有舵的船。'),
  Quote(en: 'The mind that compares itself to others never rests on its own ground.', zh: '总与他人比较的心，从不安住自己的位置。'),
  Quote(en: 'Character is what remains after the mood has passed, and it is the only thing that can be trusted on a hard day.', zh: '品格是情绪退去后留下的东西，也是困难日子里唯一可信之物。'),
  Quote(en: 'We do not become good by thinking about it once, but by deciding it every day.', zh: '变好不靠想一次，而靠每天重新决定一次。'),
  Quote(en: 'Virtue that is only spoken of is a garden without water.', zh: '只在嘴上谈说的美德，是一座没有水的花园。'),
  Quote(en: 'The same door that lets in flattery lets out self-respect.', zh: '让奉承进来的那扇门，也让自尊溜走。'),
  Quote(en: 'Whatever you feed in your heart will grow, so be careful at the table.', zh: '心里喂养什么就会长出什么，上桌前要看清楚。'),
  Quote(en: 'We do not see people as they are but as our mood frames them.', zh: '我们看到的不是真实的人，而是心情替他镶好的框。'),
  Quote(en: 'Conceit is the noise that prevents us from hearing our own doubts.', zh: '自负是让我们听不见自己疑虑的噪音。'),
  Quote(en: 'To regret deeply is to live afresh.', zh: '深刻地悔悟，等于重新活过一次。'),
  Quote(en: 'What is done is done; the only work left is what to do next.', zh: '事已如此便如此，剩下的功课是下一步做什么。'),
  Quote(en: 'Never let a small wound grow into a quarrel, for quarrels feed on what they are fed.', zh: '别让小伤口长成一场争吵，争吵靠喂养长大。'),
  Quote(en: 'The person who must always be understood exhausts others and himself.', zh: '非让人人都理解自己的人，会累坏别人也累坏自己。'),
  Quote(en: 'The hand that hurries leaves its hurry in the work.', zh: '匆忙的手，会把匆忙留在活儿里。'),
  Quote(en: 'Open your hand and you can hold more; clench it and you hold air.', zh: '张开手能拿更多，握紧拳头只抓住空气。'),
  Quote(en: 'Wisdom begins in wonder and ends in more wonder.', zh: '智慧始于惊奇，终于更大的惊奇。'),
  Quote(en: 'The wise keep their mind in many rooms, but their home in one, so that they may wander widely and still return.', zh: '智者的心思有许多房间，家却只有一个，故能远游，也终能归来。'),
  Quote(en: 'A belief you have never questioned is a guest that will not pay rent.', zh: '未经质疑的信条，是不肯付房租的房客。'),
  Quote(en: 'Every virtue has its counterfeit, and the counterfeit is usually louder.', zh: '每种美德都有赝品，而赝品往往更响亮。'),
  Quote(en: 'Only the arrogant believe they have all the time in the world.', zh: '只有傲慢的人，才相信自己有的是时间。'),
  Quote(en: 'Accept a slow beginning; there is no dishonor in unfurling late.', zh: '接受缓慢的开端，晚一些绽放并不可耻。'),
  Quote(en: 'A mistake repeated deliberately is no longer a mistake but a choice.', zh: '明知故犯的错误不再是错误，而是选择。'),
  Quote(en: 'The burden is lighter when we stop asking why it happened.', zh: '不再追问为何发生，担子便轻了一些。'),
  Quote(en: 'No one can make you small unless you lend them the measuring stick.', zh: '除非你把自己的尺子递过去，没人能把你量小。'),
  Quote(en: 'The best proof of wisdom is a quiet life.', zh: '智慧最好的证明，是一种安静的生活。'),
  Quote(en: 'We all stand on borrowed ground, moved by hands we never thanked.', zh: '我们都站在借来的土地上，被自己从未道谢的手推动。'),
  Quote(en: 'Gratitude turns what you have into enough, and enough into plenty.', zh: '感恩把手里的变成够用，又把够用变成丰足。'),
  Quote(en: 'Ask seldom what the world owes you; ask often what you owe it.', zh: '少问世界欠你什么，多问你欠它什么。'),
  Quote(en: 'The heart that never breaks has never been used.', zh: '从未破碎过的心，从未真正被用过。'),
  Quote(en: 'A slow word may save a fast friendship.', zh: '一句慢下来的话，能救一段危急的友情。'),
  Quote(en: 'There is dignity in doing small things with great care.', zh: '把小事做得极用心，本身就是一种尊严。'),
  Quote(en: 'We cannot make ourselves humble, but we can stop pretending to be what we are not.', zh: '我们无法使自己谦逊，却能停止假装不是自己。'),
  Quote(en: 'The clear mind is not empty; it is a room with the window open.', zh: '清明的心并非空无一物，而是一间开着窗的房间。'),
  Quote(en: 'Hold your opinions with an open hand.', zh: '把自己的见解摊在张开的手上。'),
  Quote(en: 'Peace of mind is not found at the end of the road; it is kept by those who carry it.', zh: '内心的安宁不在路的尽头，而在愿意随身携带它的人手里。'),
  Quote(en: 'Every teacher you dismiss as having nothing to teach you is a door you have closed with your own hand, and no key in the world will ever open it from the outside.', zh: '每个被你判定无可教益的人，都是你自己关上的门，世上的钥匙都打不开。'),
  Quote(en: 'There is a season for speaking and a season for silence, and most of our troubles come from confusing them.', zh: '说话有时，沉默有时；我们的麻烦多半来自分不清两者。'),
  Quote(en: 'Choose to lose an argument rather than to lose a friend.', zh: '宁可输掉一场争论，也别输掉一个朋友。'),
  Quote(en: 'The person who knows what he stands for cannot be bought by what is merely convenient.', zh: '知道自己坚守什么的人，不会被一时的便利收买。'),
  Quote(en: 'Never measure a life by the applause it received, but by the silence it left behind.', zh: '别用掌声衡量一生，要用它留下的寂静衡量。'),
  Quote(en: 'The mind that stays quiet in chaos is a fortress that no army can take.', zh: '喧嚣中仍安静的心，是任何军队都攻不下的堡垒。'),
  Quote(en: 'When the road is long, do not stare at the summit; give your attention to the next step.', zh: '路长时别盯着山顶，把心力放在下一步。'),
  Quote(en: 'Waste no more time arguing about what a good man should be; be one.', zh: '别再花时间争论好人该是什么样，去做一个。'),
  Quote(en: 'Slowness of speech is no defect in a person of deep thought; haste of speech is.', zh: '深思之人言慢不是缺点，言急才是。'),
  Quote(en: 'A field must lie fallow before it can bear again.', zh: '田地须先休耕，才能再次结果。'),
  Quote(en: 'If you can look at the person who wronged you and see someone shaped by a fear you have also felt, you have already won a victory that no apology could give you.', zh: '若你能看着伤害你的人，看见一个也曾被同一种恐惧塑造的人，你已赢下一场任何道歉都给不了的胜利。'),
  Quote(en: 'We spend the first half of life collecting things we think will complete us, and the second half learning that completeness was never something that could be added from the outside.', zh: '人生的前半程，我们收集自以为能让自己完整的东西；后半程才明白，完整从来不是从外面添进来的。'),
  Quote(en: 'A man may conquer a city and still be conquered by his own appetite, which is why the ancients said that the hardest of all victories is the one a man wins over himself.', zh: '有人能攻下一座城，却仍被自己的欲望攻下；古人因此说，最难赢的胜利是战胜自己。'),
  Quote(en: 'It is a strange arithmetic: the more patiently you listen, the fewer words you need, and the less you insist on being understood, the more clearly you are seen.', zh: '算术很奇妙：越肯耐心听，需要的话越少；越不强求被理解，别人越能看清你。'),
];